CREATE OR REPLACE FUNCTION public.protect_import_form()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$ BEGIN
 IF TG_TABLE_NAME='Publication' THEN
   IF EXISTS (SELECT 1 FROM "Form" WHERE id=NEW."formId" AND "sourceType"='import') THEN RAISE EXCEPTION 'import forms cannot publish' USING ERRCODE='23514'; END IF;
 ELSIF NEW."sourceType" IS DISTINCT FROM OLD."sourceType" THEN RAISE EXCEPTION 'immutable form origin' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.guard_form_document_binding()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE parent_id TEXT; parent_status TEXT; parent_tenant TEXT; parent_service TEXT; evidence_version INTEGER;
BEGIN
  IF TG_OP='UPDATE' THEN RAISE EXCEPTION 'replace draft bindings instead of mutating evidence' USING ERRCODE='23514'; END IF;
  parent_id:=CASE WHEN TG_OP='DELETE' THEN OLD."formVersionId" ELSE NEW."formVersionId" END;
  SELECT v.status, v."tenantId", f."serviceId", v."receiptEvidenceVersion" INTO parent_status,parent_tenant,parent_service,evidence_version
    FROM "FormVersion" v JOIN "Form" f ON f.id=v."formId" WHERE v.id=parent_id FOR UPDATE OF v;
  IF parent_status IS DISTINCT FROM 'draft' THEN RAISE EXCEPTION 'published form document bindings are immutable' USING ERRCODE='23514'; END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  IF NEW."tenantId" IS DISTINCT FROM parent_tenant OR NEW."serviceId" IS DISTINCT FROM parent_service OR evidence_version<>1
    THEN RAISE EXCEPTION 'form document binding scope mismatch' USING ERRCODE='23514'; END IF;
  IF (SELECT count(*) FROM "FormDocumentBinding" WHERE "formVersionId"=parent_id)>=10
    THEN RAISE EXCEPTION 'at most ten documents per form' USING ERRCODE='23514'; END IF;
  IF NOT EXISTS (SELECT 1 FROM "Document" d JOIN "DocumentVersion" v ON v."documentId"=d.id
      WHERE v.id=NEW."documentVersionId" AND d.status='published' AND d.type IN ('consent','overseas_transfer'))
    THEN RAISE EXCEPTION 'only published consent documents can be selected' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.protect_published_version()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF OLD.status = 'published' THEN
    RAISE EXCEPTION 'Published form versions are immutable' USING ERRCODE = '23514';
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_question_rules_publish()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE q record; source record; option_count integer;
BEGIN
 IF NEW.status<>'published' OR OLD.status='published' THEN RETURN NEW; END IF;
 FOR q IN SELECT * FROM "Question" WHERE "formVersionId"=NEW.id ORDER BY "order" LOOP
  SELECT count(*) INTO option_count FROM "QuestionOption" WHERE "questionId"=q.id;
  IF q.type IN ('객관식 답변','체크박스','드롭다운','행렬형 단일 선택','행렬형 복수 선택') AND option_count=0 THEN
   RAISE EXCEPTION 'Choice questions need options' USING ERRCODE='23514';
  END IF;
  IF q."selectionLimits" IS NOT NULL AND (coalesce((q."selectionLimits"->>'min')::integer,0)>option_count OR coalesce((q."selectionLimits"->>'max')::integer,0)>option_count) THEN
   RAISE EXCEPTION 'Selection count exceeds available options' USING ERRCODE='23514';
  END IF;
  IF q."condition" IS NOT NULL THEN
   SELECT * INTO source FROM "Question" WHERE "formVersionId"=NEW.id AND "stableKey"=q."condition"->>'questionId' AND "order"<q."order";
   IF NOT FOUND OR (q."condition"->>'operator'='equals' AND source.type NOT IN ('객관식 답변','드롭다운'))
    OR (q."condition"->>'operator'='includes' AND source.type<>'체크박스')
    OR NOT EXISTS (SELECT 1 FROM "QuestionOption" WHERE "questionId"=source.id AND value=q."condition"->>'value')
    OR NEW.marketing->>'nameQuestionId'=q."stableKey" OR NEW.marketing->>'emailQuestionId'=q."stableKey" OR NEW.marketing->>'smsQuestionId'=q."stableKey" THEN
    RAISE EXCEPTION 'Invalid branch reference' USING ERRCODE='23514';
   END IF;
  END IF;
 END LOOP;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.guard_subject_questions()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.status='published' AND (SELECT count(*) FROM "Question" WHERE "formVersionId"=NEW.id AND "subjectRole" IS NOT NULL)=1 THEN
    RAISE EXCEPTION 'both subject name and email are required' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.protect_published_question()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP <> 'INSERT' AND EXISTS (SELECT 1 FROM "FormVersion" WHERE id = OLD."formVersionId" AND status = 'published') THEN
    RAISE EXCEPTION 'Published questions are immutable' USING ERRCODE = '23514';
  END IF;
  IF TG_OP <> 'DELETE' AND EXISTS (SELECT 1 FROM "FormVersion" WHERE id = NEW."formVersionId" AND status = 'published') THEN
    RAISE EXCEPTION 'Published questions are immutable' USING ERRCODE = '23514';
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.protect_published_option()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE question_id TEXT;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    IF EXISTS (SELECT 1 FROM "Question" q JOIN "FormVersion" v ON v.id=q."formVersionId" WHERE q.id=OLD."questionId" AND v.status='published') THEN
      RAISE EXCEPTION 'Published options are immutable' USING ERRCODE = '23514';
    END IF;
  END IF;
  IF TG_OP <> 'DELETE' THEN
    IF EXISTS (SELECT 1 FROM "Question" q JOIN "FormVersion" v ON v.id=q."formVersionId" WHERE q.id=NEW."questionId" AND v.status='published') THEN
      RAISE EXCEPTION 'Published options are immutable' USING ERRCODE = '23514';
    END IF;
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$function$
